def seed_permissions():
    import uuid

    codes = [
        "suppliers.read",
        "suppliers.create",
        "suppliers.update",
        "suppliers.archive",
        "suppliers.prices.read",
        "suppliers.prices.manage",
        "purchasing.requests.read",
        "purchasing.requests.create",
        "purchasing.requests.manage",
        "purchasing.orders.read",
        "purchasing.orders.create",
        "purchasing.orders.confirm",
        "purchasing.orders.close",
        "purchasing.receipts.create",
        "purchasing.receipts.post",
        "production.read",
        "production.create",
        "production.manage",
        "production.stages.update",
        "production.transfers.post",
        "production.costs.read",
        "production.costs.manage",
        "production.convert",
    ]
    conn = op.get_bind()
    for code in codes:
        conn.execute(
            sa.text(
                "INSERT INTO permissions(id,code,description) VALUES (:id,:code,:description) ON CONFLICT(code) DO NOTHING"
            ),
            {
                "id": uuid.uuid5(uuid.NAMESPACE_URL, f"urn:ambs:security:{code}"),
                "code": code,
                "description": f"Phase 5: {code}",
            },
        )
    policy = {
        "SUPER_ADMIN": codes,
        "OPERATIONS": codes,
        "SALES": ["purchasing.orders.read", "production.read"],
        "ACCOUNTS": [
            "suppliers.read",
            "suppliers.prices.read",
            "purchasing.orders.read",
            "purchasing.requests.read",
            "production.read",
            "production.costs.read",
        ],
        "PACKING": ["production.read"],
        "MANAGEMENT": [
            "suppliers.read",
            "suppliers.prices.read",
            "purchasing.orders.read",
            "purchasing.requests.read",
            "production.read",
            "production.costs.read",
        ],
    }
    for role, grants in policy.items():
        for code in grants:
            conn.execute(
                sa.text(
                    "INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.code=:role AND p.code=:code ON CONFLICT DO NOTHING"
                ),
                {"role": role, "code": code},
            )


def install_guards():
    op.execute("""
    CREATE FUNCTION ambs_purchasing_document_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Commercial history cannot be deleted' USING ERRCODE='23514'; END IF;
      IF OLD.status<>'DRAFT' AND
         (to_jsonb(OLD)-ARRAY['status','updated_at','closure_reason','completed_at'])<>
         (to_jsonb(NEW)-ARRAY['status','updated_at','closure_reason','completed_at'])
      THEN RAISE EXCEPTION 'Confirmed commercial terms are immutable' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER po_history BEFORE UPDATE OR DELETE ON purchase_orders FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_document_guard();
    CREATE TRIGGER quote_history BEFORE UPDATE OR DELETE ON supplier_quotations FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_document_guard();
    CREATE TRIGGER request_history BEFORE UPDATE OR DELETE ON purchase_requests FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_document_guard();
    CREATE TRIGGER production_history BEFORE UPDATE OR DELETE ON production_orders FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_document_guard();

    CREATE FUNCTION ambs_purchasing_line_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    DECLARE parent uuid; state text;
    BEGIN
      IF TG_OP<>'INSERT' THEN
        parent:=(to_jsonb(OLD)->>TG_ARGV[1])::uuid;
        EXECUTE format('SELECT status FROM %I WHERE id=$1',TG_ARGV[0]) INTO state USING parent;
        IF state<>'DRAFT' THEN RAISE EXCEPTION 'Confirmed lines are immutable' USING ERRCODE='23514'; END IF;
      END IF;
      IF TG_OP<>'DELETE' THEN
        parent:=(to_jsonb(NEW)->>TG_ARGV[1])::uuid;
        EXECUTE format('SELECT status FROM %I WHERE id=$1',TG_ARGV[0]) INTO state USING parent;
        IF state<>'DRAFT' THEN RAISE EXCEPTION 'Cannot alter closed document lines' USING ERRCODE='23514'; END IF;
      END IF;
      IF TG_OP='DELETE' THEN RETURN OLD; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER po_line_history BEFORE INSERT OR UPDATE OR DELETE ON purchase_order_lines FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_line_guard('purchase_orders','order_id');
    CREATE TRIGGER quote_line_history BEFORE INSERT OR UPDATE OR DELETE ON supplier_quotation_lines FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_line_guard('supplier_quotations','quotation_id');
    CREATE TRIGGER request_line_history BEFORE INSERT OR UPDATE OR DELETE ON purchase_request_lines FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_line_guard('purchase_requests','request_id');
    CREATE TRIGGER receipt_line_history BEFORE INSERT OR UPDATE OR DELETE ON purchase_receipt_lines FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_line_guard('purchase_receipts','receipt_id');
    CREATE TRIGGER stage_route_history BEFORE INSERT OR UPDATE OR DELETE ON production_stages FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_line_guard('production_orders','order_id');

    CREATE FUNCTION ambs_purchase_receipt_guard() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN
      IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Receipt deletion prohibited' USING ERRCODE='23514'; END IF;
      IF OLD.status<>'DRAFT' THEN
        IF OLD.status='POSTED' AND NEW.status='REVERSED' AND NEW.reverse_key IS NOT NULL
          AND (to_jsonb(OLD)-ARRAY['status','updated_at','reverse_key'])=(to_jsonb(NEW)-ARRAY['status','updated_at','reverse_key'])
          AND (OLD.movement_id IS NULL OR EXISTS(SELECT 1 FROM stock_movements WHERE id=OLD.movement_id AND status='REVERSED')) THEN RETURN NEW; END IF;
        RAISE EXCEPTION 'Posted purchase receipt is immutable' USING ERRCODE='23514';
      END IF;
      IF NEW.status='POSTED' AND (NEW.post_key IS NULL OR NEW.posted_by IS NULL
        OR NOT EXISTS(SELECT 1 FROM purchase_receipt_lines WHERE receipt_id=NEW.id)
        OR EXISTS(SELECT 1 FROM purchase_receipt_lines r JOIN purchase_order_lines l ON l.id=r.order_line_id
          WHERE r.receipt_id=NEW.id AND l.line_type='STOCK' AND r.movement_line_id IS NULL)
        OR (NEW.movement_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM stock_movements WHERE id=NEW.movement_id AND status='POSTED')))
      THEN RAISE EXCEPTION 'Receipt requires complete posted inventory linkage' USING ERRCODE='23514'; END IF;
      RETURN NEW;
    END $$;
    CREATE TRIGGER purchase_receipt_history BEFORE UPDATE OR DELETE ON purchase_receipts FOR EACH ROW EXECUTE FUNCTION ambs_purchase_receipt_guard();

    CREATE FUNCTION ambs_purchasing_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
    BEGIN RAISE EXCEPTION 'Business event history is append only' USING ERRCODE='23514'; END $$;
    CREATE TRIGGER production_event_history BEFORE UPDATE OR DELETE ON production_events FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_append_only();
    CREATE TRIGGER schedule_event_history BEFORE UPDATE OR DELETE ON supplier_schedule_updates FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_append_only();
    CREATE TRIGGER processing_cost_history BEFORE UPDATE OR DELETE ON production_costs FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_append_only();
    CREATE TRIGGER conversion_history BEFORE UPDATE OR DELETE ON production_conversions FOR EACH ROW EXECUTE FUNCTION ambs_purchasing_append_only();
    """)
